{"code": "import os
import sys

base_path = '/home/bob/books'

books = [
    ('First_Generation', 'No Blue Sky: Built from Dust (Book 1 of 5)'),
    ('Second_Generation', 'No Blue Sky: The Oxygen Gamble (Book 2 of 5)'),
    ('Third_Generation', 'No Blue Sky: Rivers Under Mars (Book 3 of 5)'),
    ('Moon_Base_One/Moon_Base_The_Beginning', 'No Blue Sky: The Red Charter (Book 4 of 5)'),
    ('Moon_Base_One/Moon_Base_Homecoming', 'No Blue Sky: The First Martian Nation (Book 5 of 5)'),
    ('MIFECO_AI_Playbook', 'AI That Works for Small Business'),
    ('The_Unwritten_Future', 'Tomorrow is Still Open')
]

def check_book(book_rel_path, display_name):
    book_path = os.path.join(base_path, book_rel_path)
    if not os.path.exists(book_path):
        return f"❌ {display_name}: Directory not found"

    # Check for manuscript files
    manuscript_md = None
    manuscript_files = []
    for root, dirs, files in os.walk(book_path):
        for f in files:
            if f.endswith('.md') and ('manuscript' in f.lower() or 'complete' in f.lower()):
                manuscript_files.append(os.path.join(root, f))
            if f.endswith('.pdf') and 'manuscript' in f.lower():
                manuscript_md = os.path.join(root, f)
            if f.endswith('.epub'):
                pass

    # Determine manuscript status
    if manuscript_files:
        manuscript_status = f"📄 Manuscript: {len(manuscript_files)} source file(s)"
    elif manuscript_md:
        manuscript_status = "📄 Manuscript: PDF manuscript found"
    else:
        # Check for book-sources with chapters
        sources_path = os.path.join(book_path, 'book-sources')
        if os.path.exists(sources_path):
            chapter_count = len([f for f in os.listdir(sources_path) if f.endswith('.md') and f.startswith('Chapter_')])
            manuscript_status = f"📝 Chapters: {chapter_count} chapter source files"
        else:
            manuscript_status = "📝 No manuscript or chapters found"

    # Check for cover
    cover_files = []
    for root, dirs, files in os.walk(book_path):
        for f in files:
            if f.lower().endswith(('.png', '.jpg', '.jpeg')) and ('cover' in f.lower() or 'front' in f.lower()):
                cover_files.append(os.path.join(root, f))
    if cover_files:
        cover_status = f"🖼️ Cover: {len(cover_files)} image(s)"
    else:
        cover_status = "🖼️ Cover: Not found"

    # Check for EPUB
    epub_files = []
    for root, dirs, files in os.walk(book_path):
        for f in files:
            if f.endswith('.epub'):
                epub_files.append(os.path.join(root, f))
    if epub_files:
        epub_status = f"📚 EPUB: Ready ({len(epub_files)} file(s))"
    else:
        epub_status = "📚 EPUB: Not found"

    # Check for PDF (print/print-ready)
    pdf_files = []
    for root, dirs, files in os.walk(book_path):
        for f in files:
            if f.endswith('.pdf'):
                pdf_files.append(os.path.join(root, f))
    if pdf_files:
        pdf_status = f"📕 PDF: {len(pdf_files)} file(s)"
    else:
        pdf_status = "📕 PDF: Not found"

    # Pending work: look for TODO, editing logs, etc.
    pending_indicators = []
    for root, dirs, files in os.walk(book_path):
        for f in files:
            if f.lower() in ('todo.md', 'editing_pass_log.md', 'project_control_sheet.md', 'publish_checklist.md'):
                pending_indicators.append(f)
    if pending_indicators:
        pending = f"⚠️ Pending: {', '.join(pending_indicators)}"
    else:
        pending = "✅ No pending work indicated"

    return f"📚 {display_name}\n{manuscript_status}\n{cover_status}\n{epub_status}\n{pdf_status}\n{pending}"

for rel_path, name in books:
    print(check_book(rel_path, name))
    print("---")"}
